{
  "replacements": {
    "snippet::array-coerce": {
      "id": "snippet::array-coerce",
      "type": "simple",
      "description": "You can use a combination of a ternary operator and `Array.isArray` to make sure a value, `undefined`, `null` or an array is always returned as an array.",
      "example": "(val == null ? [] : Array.isArray(val) ? val : [val])\n// Or if you need to convert an iterable into an array\nArray.from(iterable)"
    },
    "snippet::array-difference": {
      "id": "snippet::array-difference",
      "type": "simple",
      "description": "You can use a `Set` with `Array.prototype.filter` to remove the values of one or more arrays from another array.",
      "example": "const difference = (array, ...values) => {\n  const rest = new Set(values.flat())\n  return array.filter((x) => !rest.has(x))\n}"
    },
    "snippet::array-filled-with": {
      "id": "snippet::array-filled-with",
      "type": "simple",
      "description": "You can use `new Array` with `Array.prototype.fill` to create an array filled with identical elements",
      "example": "new Array(length).fill(item);"
    },
    "snippet::array-flatten": {
      "id": "snippet::array-flatten",
      "type": "simple",
      "description": "You can use `Array.prototype.flat` with `Infinity` as an argument to fully flatten an array.",
      "example": "array.flat(Infinity)"
    },
    "snippet::array-from-count": {
      "id": "snippet::array-from-count",
      "type": "simple",
      "description": "You can use `Array.from` to create an array of sequential integers",
      "example": "Array.from({ length: n }, (_, i) => i);"
    },
    "snippet::array-from-count-with-start": {
      "id": "snippet::array-from-count-with-start",
      "type": "simple",
      "description": "You can use `Array.from` to create an array of sequential integers starting from a specific integer",
      "example": "Array.from({ length: end - start }, (_, i) => i + start);"
    },
    "snippet::array-last": {
      "id": "snippet::array-last",
      "type": "simple",
      "description": "You can use `arr.at(-1)` if supported or `arr[arr.length - 1]` to get the last element of an array.",
      "example": "const last = (arr) => arr.at(-1);\n// or in older environments\nconst lastLegacy = (arr) => arr[arr.length - 1]"
    },
    "snippet::array-slice-exclude-last-n": {
      "id": "snippet::array-slice-exclude-last-n",
      "type": "simple",
      "description": "You can get all but the last n elements using `array.slice`",
      "example": "array.slice(0, array.length - n)"
    },
    "snippet::array-union": {
      "id": "snippet::array-union",
      "type": "simple",
      "description": "You can use a combination of the spread operator and `Set` to create a union of two arrays.",
      "example": "const union = (a, b) => [...new Set([...a, ...b])]"
    },
    "snippet::array-unique": {
      "id": "snippet::array-unique",
      "type": "simple",
      "description": "You can convert to and from a `Set` to remove duplicates from an array.",
      "example": "const unique = (arr) => [...new Set(arr)]"
    },
    "snippet::assert": {
      "id": "snippet::assert",
      "type": "simple",
      "description": "You can use a simple function to assert a value or an expression.",
      "example": "function assert(val, msg) {\n  if (!val) throw new Error(msg)\n}"
    },
    "snippet::async-each": {
      "id": "snippet::async-each",
      "type": "simple",
      "description": "You can use `Promise.all` with `Array.prototype.map` to do an async action with an array of items.",
      "example": "Promise.all(items.map(asyncFn))"
    },
    "snippet::async-function-constructor": {
      "id": "snippet::async-function-constructor",
      "type": "simple",
      "description": "You can get the `AsyncFunction` using `async function`.",
      "example": "const AsyncFunction = (async () => {}).constructor"
    },
    "snippet::bail": {
      "id": "snippet::bail",
      "type": "simple",
      "description": "You can use a simple `if` statement to throw an error when a truthy value is provided.",
      "example": "if (error) {\n  throw error\n}"
    },
    "snippet::base64": {
      "id": "snippet::base64",
      "type": "simple",
      "description": "Every modern runtime provides a way to convert byte array to and from base64.",
      "example": "// From base64 to Uint8Array\nconst bytes = Uint8Array.fromBase64(base64)\n// From Uint8Array to base64\nconst base64 = bytes.toBase64()"
    },
    "snippet::base64-id": {
      "id": "snippet::base64-id",
      "type": "simple",
      "description": "You can use `crypto.randomBytes` with `Buffer.prototype.toString` to generate a random base64 id",
      "example": "import crypto from 'node:crypto'\nconst id = crypto.randomBytes(15).toString('base64').replaceAll('+', '-').replaceAll('/', '_')"
    },
    "snippet::call-bind": {
      "id": "snippet::call-bind",
      "type": "simple",
      "description": "Every modern runtime provides a way to bind to the `call` method of a function.",
      "example": "const fnBound = Function.call.bind(fn)"
    },
    "snippet::char-last": {
      "id": "snippet::char-last",
      "type": "simple",
      "description": "You can use `str.at(-1)` if supported or `str[str.length - 1]` to get the last character of a string.",
      "example": "const last = (str) => str.at(-1);\n// or in older environments\nconst lastLegacy = (str) => str[str.length - 1]"
    },
    "snippet::collapse-whitespace": {
      "id": "snippet::collapse-whitespace",
      "type": "simple",
      "description": "You can use `String.prototype.replace` with a `/\\s+/g` regular expression to collapse runs of whitespace into a single space, and `String.prototype.trim` to also remove it from the start and end.",
      "example": "const collapseWhiteSpace = (str) => str.replace(/\\s+/g, ' ')\n// or to also trim the ends\nconst collapseWhiteSpaceAndTrim = (str) => str.trim().replace(/\\s+/g, ' ')"
    },
    "snippet::comver-to-semver": {
      "id": "snippet::comver-to-semver",
      "type": "simple",
      "description": "You can use a ternary operator and string concatenation to add a trailing `.0`.",
      "example": "const comverToSemver = (comver) => comver.includes('.') ? `${comver}.0` : `${comver}.0.0`"
    },
    "snippet::count-occurrences": {
      "id": "snippet::count-occurrences",
      "type": "simple",
      "description": "You can iterate through `String.prototype.indexOf` to count how often a character or substring occurs in a string.",
      "example": "const countOccurrences = (str, substr) => {\n  let count = 0\n  let index = str.indexOf(substr)\n  while (index !== -1) {\n    count++\n    index = str.indexOf(substr, index + substr.length)\n  }\n  return count\n}"
    },
    "snippet::dns-equal": {
      "id": "snippet::dns-equal",
      "type": "simple",
      "description": "DNS names compare case-insensitively for ASCII letters only (RFC 4343). You can lowercase `A`-`Z` with `String.prototype.replace` and compare the results. `String.prototype.toLowerCase` also lowercases non-ASCII characters, so use it only if your names are already ASCII.",
      "example": "const lowerAscii = (str) => str.replace(/[A-Z]/g, (c) => c.toLowerCase())\nconst dnsEqual = (a, b) => lowerAscii(a) === lowerAscii(b)\n// or, if both names are ASCII-only\nconst dnsEqualAscii = (a, b) => a.toLowerCase() === b.toLowerCase()"
    },
    "snippet::english-days": {
      "id": "snippet::english-days",
      "type": "simple",
      "description": "You can use an array of English weekday names instead of a dependency.",
      "example": "const days = [ \"sunday\", \"monday\", \"tuesday\", \"wednesday\", \"thursday\", \"friday\", \"saturday\" ]"
    },
    "snippet::error-with-code": {
      "id": "snippet::error-with-code",
      "type": "simple",
      "description": "You can use `Object.assign` to add a `code` and any other properties to an error.",
      "example": "const err = Object.assign(new Error('Not found'), { code: 'ENOENT', path })"
    },
    "snippet::find-first-defined": {
      "id": "snippet::find-first-defined",
      "type": "simple",
      "description": "You can use `Array.prototype.find` to find a first defined item.",
      "example": "const defined = (...args) => args.find((v) => v !== undefined)"
    },
    "snippet::for-own": {
      "id": "snippet::for-own",
      "type": "simple",
      "description": "You can use `Object.keys(obj).forEach` to iterate over the own enumerable properties of an object.",
      "example": "Object.keys(obj).forEach(key => {\n  const value = obj[key];\n  // do something\n});"
    },
    "snippet::get-iterator": {
      "id": "snippet::get-iterator",
      "type": "simple",
      "description": "Every modern runtime provides a way to get the iterator function through the `Symbol.iterator` symbol.",
      "example": "const iterator = obj[Symbol.iterator]?.()"
    },
    "snippet::has-ansi": {
      "id": "snippet::has-ansi",
      "type": "simple",
      "description": "You can use the `includes` method on the string to check if a specific ANSI byte is present.",
      "example": "string.includes(\"\\u001b\") || string.includes(\"\\u009b\")"
    },
    "snippet::has-argv": {
      "id": "snippet::has-argv",
      "type": "simple",
      "description": "You can use the `includes` method on the `process.argv` array to check if a flag is present.",
      "example": "process.argv.includes('--flag')"
    },
    "snippet::home-or-tmp": {
      "id": "snippet::home-or-tmp",
      "type": "simple",
      "description": "You can use `homedir() || tmpdir()` in cases where the home directory either isn't set or doesn't exist.",
      "example": "const homeOrTempDir = homedir() || tmpdir()"
    },
    "snippet::indent-string": {
      "id": "snippet::indent-string",
      "type": "simple",
      "description": "You can indent every non-empty line with `String.prototype.replace`, or use `/^/gm` to also indent empty lines, matching the package's `includeEmptyLines` option.",
      "example": "const indentString = (string, count = 1, indent = ' ') =>\n  string.replace(/^(?!\\s*$)/gm, indent.repeat(count));"
    },
    "snippet::is-alphabetical": {
      "id": "snippet::is-alphabetical",
      "type": "simple",
      "description": "You can check if a character is an ASCII letter by using a case-insensitive `RegExp`.",
      "example": "const isAlphabetical = (char) => /^[a-z]$/i.test(char);"
    },
    "snippet::is-arguments": {
      "id": "snippet::is-arguments",
      "type": "simple",
      "description": "You can use `Object.prototype.toString.call(obj) === \"[object Arguments]\"`",
      "example": "const isArguments = (val) => Object.prototype.toString.call(val) === \"[object Arguments]\";"
    },
    "snippet::is-arraybuffer": {
      "id": "snippet::is-arraybuffer",
      "type": "simple",
      "description": "You can use `instanceof ArrayBuffer`, or if cross-realm, use `Object.prototype.toString.call(obj) === \"[object ArrayBuffer]\"`",
      "example": "const isArrayBuffer = obj instanceof ArrayBuffer;\n// for cross-realm\nconst isArrayBufferCrossRealm = Object.prototype.toString.call(obj) === \"[object ArrayBuffer]\""
    },
    "snippet::is-async-function": {
      "id": "snippet::is-async-function",
      "type": "simple",
      "description": "You can use `typeof` and `Object.prototype.toString.call` to check if it's an async function",
      "example": "const isAsyncFunction = (obj) => typeof obj === \"function\" && Object.prototype.toString.call(obj) === \"[object AsyncFunction]\""
    },
    "snippet::is-aws-lambda": {
      "id": "snippet::is-aws-lambda",
      "type": "simple",
      "description": "You can check if the current environment is an AWS Lambda by checking if the `LAMBDA_TASK_ROOT` environment variables are set.",
      "example": "Boolean(process.env.LAMBDA_TASK_ROOT)"
    },
    "snippet::is-bigint": {
      "id": "snippet::is-bigint",
      "type": "simple",
      "description": "You can use `typeof` to check if a value is a bigint.",
      "example": "typeof value === \"bigint\""
    },
    "snippet::is-boolean": {
      "id": "snippet::is-boolean",
      "type": "simple",
      "description": "You can use `typeof` to check if a value is a boolean.",
      "example": "typeof value === \"boolean\""
    },
    "snippet::is-ci": {
      "id": "snippet::is-ci",
      "type": "simple",
      "description": "Every major CI provider sets a `CI` environment variable that you can use to detect if you're running in a CI environment.",
      "example": "Boolean(process.env.CI)"
    },
    "snippet::is-date": {
      "id": "snippet::is-date",
      "type": "simple",
      "description": "You can use `instanceof Date`, or if cross-realm, use `Object.prototype.toString.call(v) === \"[object Date]\"`",
      "example": "const isDate = v instanceof Date;\n// for cross-realm\nconst isDateCrossRealm = Object.prototype.toString.call(v) === \"[object Date]\""
    },
    "snippet::is-decimal": {
      "id": "snippet::is-decimal",
      "type": "simple",
      "description": "You can check if a character, or a character code, is a decimal digit by comparing its character code against the `0`-`9` range.",
      "example": "const isDecimal = (character) => {\n  const code =\n    typeof character === 'string' ? character.charCodeAt(0) : character;\n  return code >= 48 && code <= 57;\n};"
    },
    "snippet::is-deflate-buffer": {
      "id": "snippet::is-deflate-buffer",
      "type": "simple",
      "description": "You can check the first two bytes of a buffer to detect if it's compressed using deflate.",
      "example": "function isDeflate(buf) {\n  if (buf.length < 2 || buf[0] !== 0x78) return false;\n  const b = buf[1];\n  return b === 1 || b === 0x9c || b === 0xda;\n}"
    },
    "snippet::is-directory": {
      "id": "snippet::is-directory",
      "type": "simple",
      "description": "You can call `isDirectory()` on the result of `stat` from `node:fs/promises`, or of `statSync` from `node:fs`, treating an `ENOENT` error as `false`.",
      "example": "import { stat } from 'node:fs/promises'\n\nconst isDirectory = async (filepath) => {\n  try {\n    return (await stat(filepath)).isDirectory()\n  } catch (err) {\n    if (err.code === 'ENOENT') return false\n    throw err\n  }\n}"
    },
    "snippet::is-dotfile": {
      "id": "snippet::is-dotfile",
      "type": "simple",
      "description": "You can test whether a path ends in a dotfile such as `.gitignore` using a regular expression.",
      "example": "const isDotfile = (str) => /(?:\\/|^)\\.[^/.][^/]*$/.test(str)"
    },
    "snippet::is-electron": {
      "id": "snippet::is-electron",
      "type": "simple",
      "description": "You can detect Electron by checking the renderer process type, `process.versions.electron`, or the user agent.",
      "example": "function isElectron() {\n  return Boolean(\n    globalThis.window?.process?.type === \"renderer\" ||\n      globalThis.process?.versions?.electron ||\n      globalThis.navigator?.userAgent?.includes(\"Electron\")\n  );\n}"
    },
    "snippet::is-equal": {
      "id": "snippet::is-equal",
      "type": "simple",
      "description": "You can determine if two values are equal using regular equality checks.",
      "example": "a === b"
    },
    "snippet::is-even": {
      "id": "snippet::is-even",
      "type": "simple",
      "description": "You can use the modulo operator to check if a number is even.",
      "example": "(n % 2) === 0"
    },
    "snippet::is-function": {
      "id": "snippet::is-function",
      "type": "simple",
      "description": "You can use `typeof` to check if a value is a function.",
      "example": "typeof value === \"function\""
    },
    "snippet::is-generator-function": {
      "id": "snippet::is-generator-function",
      "type": "simple",
      "description": "You can use `typeof` and `Object.prototype.toString.call` to check if a value is a generator function",
      "example": "const isGeneratorFunction = (obj) => typeof obj === \"function\" && Object.prototype.toString.call(obj) === \"[object GeneratorFunction]\""
    },
    "snippet::is-gzip-buffer": {
      "id": "snippet::is-gzip-buffer",
      "type": "simple",
      "description": "You can check first three bytes of a buffer to detect if it is a gzip file.",
      "example": "function isGzip(buf) {\n  if (buf.length < 3) return false;\n  return buf[0] === 31 && buf[1] === 139 && buf[2] === 8;\n}"
    },
    "snippet::is-hexadecimal": {
      "id": "snippet::is-hexadecimal",
      "type": "simple",
      "description": "You can check if a character is a hexadecimal digit by using a `RegExp` with the `ASCII_Hex_Digit` Unicode property.",
      "example": "const isHexadecimal = (char) => /^\\p{ASCII_Hex_Digit}$/u.test(char);"
    },
    "snippet::is-identifier-name": {
      "id": "snippet::is-identifier-name",
      "type": "simple",
      "description": "You can test a string against the `ID_Start` and `ID_Continue` Unicode properties to check whether it is a valid identifier name, and so usable as an unquoted property.",
      "example": "const isProperty = (str) => /^[$_\\p{ID_Start}][$\\p{ID_Continue}]*$/u.test(str)"
    },
    "snippet::is-in-ssh": {
      "id": "snippet::is-in-ssh",
      "type": "simple",
      "description": "You can check if the current environment is SSH by checking if the `SSH_CONNECTION` environment variable is set.",
      "example": "Boolean(process.env.SSH_CONNECTION)"
    },
    "snippet::is-interactive": {
      "id": "snippet::is-interactive",
      "type": "simple",
      "description": "You can check if the current environment is interactive using `process.stdout.isTTY` and checking that it is not running in CI.",
      "example": "Boolean(stream?.isTTY && !process.env.CI)"
    },
    "snippet::is-jpg-buffer": {
      "id": "snippet::is-jpg-buffer",
      "type": "simple",
      "description": "You can check the first three bytes of a buffer against the JPEG file signature to detect if it is a JPEG image.",
      "example": "function isJpg(buf) {\n  if (!buf || buf.length < 3) return false;\n  return buf[0] === 0xff && buf[1] === 0xd8 && buf[2] === 0xff;\n}"
    },
    "snippet::is-lower-case": {
      "id": "snippet::is-lower-case",
      "type": "simple",
      "description": "You can compare the string against its lower-cased form to determine if the string is entirely lower case",
      "example": "const isLowerCase = (input, locale) =>\n  input.toLocaleLowerCase(locale) === input &&\n  input !== input.toLocaleUpperCase(locale)"
    },
    "snippet::is-map": {
      "id": "snippet::is-map",
      "type": "simple",
      "description": "You can use `instanceof Map` to check if a value is a `Map`, or if cross-realm, use `Object.prototype.toString.call(v) === \"[object Map]\"`",
      "example": "const isMap = v instanceof Map;\n// for cross-realm\nconst isMapCrossRealm = Object.prototype.toString.call(v) === \"[object Map]\""
    },
    "snippet::is-negative": {
      "id": "snippet::is-negative",
      "type": "simple",
      "description": "You can check if a number is less than 0 to determine if it's negative.",
      "example": "(n) => n < 0"
    },
    "snippet::is-negative-zero": {
      "id": "snippet::is-negative-zero",
      "type": "simple",
      "description": "You can use `Object.is` to check if a value is negative zero.",
      "example": "Object.is(n, -0)"
    },
    "snippet::is-nil": {
      "id": "snippet::is-nil",
      "type": "simple",
      "description": "You can check if a value is `null` or `undefined` using loose equality with `null`.",
      "example": "value == null"
    },
    "snippet::is-node": {
      "id": "snippet::is-node",
      "type": "simple",
      "description": "You can check `process.versions.node` to detect Node.js.",
      "example": "const isNode = Boolean(globalThis.process?.versions?.node)"
    },
    "snippet::is-npm": {
      "id": "snippet::is-npm",
      "type": "simple",
      "description": "If the current environment is npm the `npm_config_user_agent` environment variable will be set and start with `\"npm\"`.",
      "example": "const isNpm = process.env.npm_config_user_agent?.startsWith(\"npm\")"
    },
    "snippet::is-null": {
      "id": "snippet::is-null",
      "type": "simple",
      "description": "You can check if a value is `null` using regular equality checks.",
      "example": "value === null"
    },
    "snippet::is-number": {
      "id": "snippet::is-number",
      "type": "simple",
      "description": "You can use `typeof` to check if a value is a number.",
      "example": "typeof value === \"number\""
    },
    "snippet::is-object": {
      "id": "snippet::is-object",
      "type": "simple",
      "description": "You can use `typeof` to check if a value is an object and `Object.getPrototypeOf` to ensure it's a plain object.",
      "example": "const isObject = (obj) => obj && typeof obj === \"object\" && (Object.getPrototypeOf(obj) === null || Object.getPrototypeOf(obj) === Object.prototype);"
    },
    "snippet::is-object-or-function": {
      "id": "snippet::is-object-or-function",
      "type": "simple",
      "description": "You can use `typeof` to check if a value is an object or a function.",
      "example": "const isObjectOrFunction = (v) => v !== null && (typeof v === \"object\" || typeof v === \"function\");"
    },
    "snippet::is-odd": {
      "id": "snippet::is-odd",
      "type": "simple",
      "description": "You can use the modulo operator to check if a number is odd.",
      "example": "(n % 2) === 1"
    },
    "snippet::is-path-equal-cwd": {
      "id": "snippet::is-path-equal-cwd",
      "type": "simple",
      "description": "You can check if a path equals the current working directory using `path.relative`.",
      "example": "import { relative } from 'node:path'\n\nconst isPathCwd = (p) => !relative(p, process.cwd())"
    },
    "snippet::is-png-buffer": {
      "id": "snippet::is-png-buffer",
      "type": "simple",
      "description": "You can check the first eight bytes of a buffer against the PNG file signature to detect if it is a PNG image.",
      "example": "function isPng(buf) {\n  if (!buf || buf.length < 8) return false;\n  return buf[0] === 0x89 && buf[1] === 0x50\n    && buf[2] === 0x4e && buf[3] === 0x47\n    && buf[4] === 0x0d && buf[5] === 0x0a\n    && buf[6] === 0x1a && buf[7] === 0x0a;\n}"
    },
    "snippet::is-posix-bracket": {
      "id": "snippet::is-posix-bracket",
      "type": "simple",
      "description": "You can test for a POSIX bracket expression such as `[:alpha:]` using a regular expression.",
      "example": "const isPosixBracket = (str) => /\\[([:.=+])(?:[^\\[\\]]|)+\\1\\]/.test(str);"
    },
    "snippet::is-primitive": {
      "id": "snippet::is-primitive",
      "type": "simple",
      "description": "You can check `typeof` of a value to determine if it's a primitive. Note that `typeof null` is `\"object\"` so you need to check for `null` separately.",
      "example": "const isPrimitive = (value) => value === null || (typeof value !== \"function\" && typeof value !== \"object\");"
    },
    "snippet::is-redirect": {
      "id": "snippet::is-redirect",
      "type": "simple",
      "description": "You can check the status code against the set of codes (300, 301, 302, 303, 305, 307 and 308) with a `Set` or an array.",
      "example": "const redirectCodes = new Set([300, 301, 302, 303, 305, 307, 308])\nconst isRedirect = (statusCode) => redirectCodes.has(statusCode)"
    },
    "snippet::is-regexp": {
      "id": "snippet::is-regexp",
      "type": "simple",
      "description": "You can use `instanceof RegExp` to check if a value is a regular expression, or if cross-realm, use `Object.prototype.toString.call(v) === \"[object RegExp]\"`.",
      "example": "const isRegExp = (v) => v instanceof RegExp;\n// for cross-realm\nconst isRegExpCrossRealm = Object.prototype.toString.call(v) === \"[object RegExp]\";"
    },
    "snippet::is-root-user": {
      "id": "snippet::is-root-user",
      "type": "simple",
      "description": "You can use `process.getuid?.()` to check if a user is a root user.",
      "example": "const isRootUser = process.getuid?.() === 0"
    },
    "snippet::is-set": {
      "id": "snippet::is-set",
