      "description": "You can use `typeof` to check if a value is a string.",
      "example": "typeof value === \"string\""
    },
    "snippet::is-supported-regexp-flag": {
      "id": "snippet::is-supported-regexp-flag",
      "type": "simple",
      "description": "The `RegExp` constructor throws on an unsupported or invalid flag, so you can check support with a `try`/`catch`.",
      "example": "const isSupportedRegexpFlag = (flag) => {\n  try {\n    RegExp(\"\", flag);\n    return true;\n  } catch {\n    return false;\n  }\n};"
    },
    "snippet::is-symbol": {
      "id": "snippet::is-symbol",
      "type": "simple",
      "description": "You can use `typeof` to check if a value is a symbol.",
      "example": "typeof value === \"symbol\""
    },
    "snippet::is-touch-device": {
      "id": "snippet::is-touch-device",
      "type": "simple",
      "description": "You can check if the current device is a touch device by checking the `'ontouchstart'` propery of the `window` object and `maxTouchPoints` of the `navigator` object.",
      "example": "const isTouchDevice = window && ('ontouchstart' in window || navigator.maxTouchPoints)"
    },
    "snippet::is-travis": {
      "id": "snippet::is-travis",
      "type": "simple",
      "description": "You can check if the current environment is Travis CI by checking if the `TRAVIS` environment variable is set.",
      "example": "Boolean(process.env.TRAVIS)"
    },
    "snippet::is-typed-array": {
      "id": "snippet::is-typed-array",
      "type": "simple",
      "description": "You can check if a value is a Typed Array using `ArrayBuffer.isView` and checking if it is not a `DataView`.",
      "example": "const isTypedArray = (v) => ArrayBuffer.isView(v) && !(v instanceof DataView);"
    },
    "snippet::is-unc-path": {
      "id": "snippet::is-unc-path",
      "type": "simple",
      "description": "You can test for a Windows UNC path such as `\\\\server\\share` using a regular expression.",
      "example": "const isUncPath = (filepath) => /^[\\\\\\/]{2,}[^\\\\\\/]+[\\\\\\/]+[^\\\\\\/]+/.test(filepath)"
    },
    "snippet::is-undefined": {
      "id": "snippet::is-undefined",
      "type": "simple",
      "description": "You can use `typeof` to check if a value is `undefined`.",
      "example": "typeof value === \"undefined\""
    },
    "snippet::is-weakmap": {
      "id": "snippet::is-weakmap",
      "type": "simple",
      "description": "You can use `instanceof WeakMap` to check if a value is a `WeakMap`, or if cross-realm, use `Object.prototype.toString.call(v) === \"[object WeakMap]\"`",
      "example": "const isWeakMap = v instanceof WeakMap;\n// for cross-realm\nconst isWeakMapCrossRealm = Object.prototype.toString.call(v) === \"[object WeakMap]\""
