    "snippet::is-whitespace": {
      "id": "snippet::is-whitespace",
      "type": "simple",
      "description": "You can check if a string contains only whitespace with `RegExp` or by trimming it and comparing it to an empty string.",
      "example": "const isWhitespace = (str) => /^\\s*$/.test(str);"
    },
    "snippet::is-windows": {
      "id": "snippet::is-windows",
      "type": "simple",
      "description": "You can check if the current environment is Windows by checking if `process.platform` is equal to \"win32\".",
      "example": "const isWindows = () => process.platform === \"win32\";"
    },
    "snippet::is-word-character": {
      "id": "snippet::is-word-character",
      "type": "simple",
      "description": "You can check if a character is a word character with a `RegExp`.",
      "example": "const isWordChar = (c) => /\\w/.test(c);"
    },
    "snippet::is-wsl": {
      "id": "snippet::is-wsl",
      "type": "simple",
      "description": "You can check if the current environment is WSL by checking if the `WSL_DISTRO_NAME` environment variable is set.",
      "example": "Boolean(process.env.WSL_DISTRO_NAME)"
    },
    "snippet::json-file": {
      "id": "snippet::json-file",
      "type": "simple",
      "description": "You can use `JSON` and `node:fs` to read and write JSON files.",
      "example": "import * as fs from 'node:fs/promises'\nfs.readFile(file, 'utf8').then(JSON.parse)\nfs.writeFile(file, JSON.stringify(data, null, 2) + '\\n')"
    },
    "snippet::lazy-property": {
      "id": "snippet::lazy-property",
      "type": "simple",
      "description": "You can define a self-overwriting getter that computes the value on first access and then replaces itself with a plain data property using `Object.defineProperty`.",
      "example": "const obj = {\n  get prop() {\n    const value = computeExpensiveValue();\n    Object.defineProperty(this, 'prop', { value, writable: true, configurable: true, enumerable: true });\n    return value;\n  }\n};"
    },
    "snippet::longest": {
      "id": "snippet::longest",
      "type": "simple",
      "description": "You can use `Array.prototype.reduce` to find the longest string in an array.",
      "example": "const longest = (arr) => arr.reduce((a, b) => (b.length > a.length ? b : a), arr[0])"
    },
    "snippet::math-random": {
      "id": "snippet::math-random",
      "type": "simple",
      "description": "You can use `Math.random()` or `crypto.getRandomValues` if cryptographic randomness is required.",
      "example": "crypto.getRandomValues(new Uint32Array(1))[0] / (2 ** 32);\n// or\nMath.random();"
    },
    "snippet::merge-descriptors": {
      "id": "snippet::merge-descriptors",
      "type": "simple",
      "description": "You can copy property descriptors (including getters and setters) from one object to another with `Object.defineProperties` and `Object.getOwnPropertyDescriptors`. To skip properties the destination already has, loop over `Object.getOwnPropertyNames` instead.",
      "example": "const mergeDescriptors = (destination, source) =>\n  Object.defineProperties(destination, Object.getOwnPropertyDescriptors(source))"
    },
    "snippet::min-indent": {
      "id": "snippet::min-indent",
      "type": "simple",
      "description": "You can use a regular expression with `Array.prototype.reduce` to find the shortest leading whitespace across the lines of a string.",
      "example": "const minIndent = (string) => (string.match(/^[ \\t]*(?=\\S)/gm) ?? ['']).reduce((r, a) => Math.min(r, a.length), Infinity)"
    },
    "snippet::nanoseconds-to-seconds": {
      "id": "snippet::nanoseconds-to-seconds",
      "type": "simple",
      "description": "The result of `process.hrtime.bigint()` can be converted to a number and divided by `1e9` (1 billion) to compute the seconds.",
      "example": "const seconds = Number(nanoseconds) / 1e9"
    },
    "snippet::noop": {
      "id": "snippet::noop",
      "type": "simple",
      "description": "You can use an arrow function `() => {}` for a noop function.",
      "example": "const noop = () => {}"
    },
    "snippet::object-exclude": {
      "id": "snippet::object-exclude",
      "type": "simple",
      "description": "You can use `Object.fromEntries` with `Object.entries` and `Array.prototype.filter` to exclude specific keys from an object.",
      "example": "const objectExclude = (obj, keys) => Object.fromEntries(Object.entries(obj).filter(([k]) => !keys.includes(k)));"
    },
    "snippet::object-filter": {
      "id": "snippet::object-filter",
      "type": "simple",
      "description": "You can use `Object.fromEntries` with `Object.entries` and `Array.prototype.filter` to filter an object's properties.",
      "example": "const objectFilter = (obj, fn) => Object.fromEntries(Object.entries(obj).filter(fn));"
    },
    "snippet::object-invert-key-value": {
      "id": "snippet::object-invert-key-value",
      "type": "simple",
      "description": "You can use `Object.fromEntries` with `Object.entries` to invert keys and values.",
      "example": "Object.fromEntries(Object.entries(object).map(([k, v]) => [v, k]))"
    },
    "snippet::object-iterate": {
      "id": "snippet::object-iterate",
      "type": "simple",
      "description": "You can use a `for...of` loop over `Object.entries` to iterate an object's own enumerable properties, and `break` to stop early.",
      "example": "for (const [key, value] of Object.entries(obj)) {\n  if (key === 'stop') break\n  // do something\n}\n// Or for arrays\nfor (const [index, value] of arr.entries()) {\n  // do something\n}"
    },
    "snippet::object-lowercase-keys": {
      "id": "snippet::object-lowercase-keys",
      "type": "simple",
      "description": "You can use `Object.fromEntries` with `Object.entries` and `Array.prototype.map` to lowercase the keys of an object.",
      "example": "Object.fromEntries(Object.entries(object).map(([k, v]) => [k.toLowerCase(), v]))"
    },
    "snippet::object-map": {
      "id": "snippet::object-map",
      "type": "simple",
      "description": "You can use `Object.fromEntries` with `Object.entries` and `Array.prototype.map` to map an object's properties.",
      "example": "const objectMap = (obj, fn) => Object.fromEntries(Object.entries(obj).map(([k, v]) => fn(k, v)));"
    },
    "snippet::object-reduce": {
      "id": "snippet::object-reduce",
      "type": "simple",
      "description": "You can use `Object.entries` and `Array.prototype.reduce`.",
      "example": "const objectReduce = (obj, fn, initial) => Object.entries(obj).reduce((acc, [k, v]) => fn(acc, k, v), initial);"
    },
    "snippet::path-key": {
      "id": "snippet::path-key",
      "type": "simple",
      "description": "You can use `Object.keys` with `Array.prototype.findLast` to find the case-insensitive `PATH` environment variable key.",
      "example": "const pathKey = Object.keys(process.env).findLast((k) => k.toUpperCase() === 'PATH') ?? 'PATH';"
    },
    "snippet::path-relative": {
      "id": "snippet::path-relative",
      "type": "simple",
      "description": "You can use `relative` and `dirname` from `node:path` to get the relative path from one file to another.",
      "example": "import { dirname, relative } from 'node:path'\n\nconst relativeFromFile = (fromFile, to) => relative(dirname(fromFile), to)"
