      "id": "snippet::sponge-case",
      "type": "simple",
      "description": "You can use `Array.from` to iterate over the characters of a string and randomly change the case of each one.",
      "example": "const spongeCase = (str, locale) =>\n  Array.from(str, (c) =>\n    Math.random() > 0.5 ? c.toLocaleUpperCase(locale) : c.toLocaleLowerCase(locale)\n  ).join('')"
    },
    "snippet::strip-bom": {
      "id": "snippet::strip-bom",
      "type": "simple",
      "description": "You can check if the first character of the string is the BOM and strip it using `String.prototype.slice` if it is.",
      "example": "str.charCodeAt(0) === 0xFEFF ? str.slice(1) : str;"
