    "snippet::to-identifier": {
      "id": "snippet::to-identifier",
      "type": "simple",
      "description": "You can transform a string into an identifier (alphanumeric PascalCase) using `map` and a regular expression.",
      "example": "function toIdentifier(str) {\n  return str\n    .split(' ')\n    .map(t => t.charAt(0).toUpperCase() + t.slice(1))\n    .join('')\n    .replace(/[^ _0-9a-z]/gi, '')\n}"
    },
    "snippet::trim-repeated-characters": {
      "id": "snippet::trim-repeated-characters",
      "type": "simple",
      "description": "You can trim repeated sequences of characters using `String.prototype.replace`.",
      "example": "// Normal character\nstring.replace(/-{2,}/g, '-')\n\n// Special character\nstring.replace(/\\.{2,}/g, '.')\n\n// Multi-character sequence\nstring.replace(/(?:abc){2,}/g, 'abc')"
